class StandardThreadExecutor:
    DEFAULT_MIN_THREADS, DEFAULT_MAX_THREADS, DEFAULT_MAX_IDLE_TIME = 20, 200, 60000
    def __init__(self, coreThreads=20, maxThreads=200, *args, **kwargs):
        capacity, factory, keep = maxThreads, DefaultThreadFactory('pool'), 60
        if len(args) <= 2:
            if args: capacity = args[0]
            if len(args) == 2: factory = args[1]
        else:
            keep = _seconds(args[0], args[1]); capacity = args[2]
            if len(args)>3: factory = args[3]
        capacity = kwargs.get('queueCapacity', capacity)
        if coreThreads < 0 or maxThreads <= 0 or coreThreads > maxThreads or keep < 0: raise ValueError('invalid pool sizes')
        self.coreThreads, self.maxThreads, self.maxSubmittedTaskCount = coreThreads, maxThreads, capacity+maxThreads
        self.factory, self.keepAliveTime = factory, keep
        self._queue = ExecutorQueue(); self._queue.setStandardThreadExecutor(self)
        self._lock = threading.RLock(); self._threads = set(); self._count = self._active = 0; self._shutdown = False
    def submit(self, fn, *args, **kwargs):
        future = concurrent.futures.Future()
        future.get = lambda timeout=None, unit=None: future.result(None if timeout is None else _seconds(timeout, unit))
        def run():
            if future.set_running_or_notify_cancel():
                try: future.set_result((fn if callable(fn) else fn.run)(*args, **kwargs))
                except BaseException as e: future.set_exception(e)
        self.execute(run)
        return future
    def execute(self, command):
        if command is None: raise ValueError('command is required')
        with self._lock:
            if self._shutdown or self._count >= self.maxSubmittedTaskCount: raise RejectedExecutionException('Task rejected')
            self._count += 1
            if len(self._threads)<self.coreThreads or (len(self._threads)<self.maxThreads and self._count>len(self._threads)):
                t = self.factory.newThread(lambda: self._worker(command))
                self._threads.add(t); t.start()
            else: self._queue.put(command)
    def _worker(self, command):
        try:
            while command is not None:
                with self._lock: self._active += 1
                try: (command if callable(command) else command.run)()
                except BaseException: pass
                finally:
                    with self._lock: self._active -= 1; self._count -= 1
                while True:
                    with self._lock:
                        if self._shutdown and self._queue.empty(): return
                    try: command = self._queue.get(timeout=max(.01, min(self.keepAliveTime, .1))); break
                    except queue.Empty:
                        with self._lock:
                            if len(self._threads)>self.coreThreads: return
        finally:
            with self._lock: self._threads.discard(threading.current_thread())
    def shutdown(self, wait=False):
        with self._lock: self._shutdown = True
        if wait: self.awaitTermination(float('inf'))
    def shutdownNow(self):
        self.shutdown(); removed=[]
        with self._lock:
            while not self._queue.empty(): removed.append(self._queue.get_nowait()); self._count -= 1
        return removed
    def awaitTermination(self, timeout, unit=None):
        end = time.monotonic()+_seconds(timeout, unit)
        for t in list(self._threads): t.join(None if timeout == float('inf') else max(0,end-time.monotonic()))
        return self.isTerminated()
    def isShutdown(self): return self._shutdown
    def isTerminated(self): return self._shutdown and not self._threads
    def getSubmittedTasksCount(self): return self._count
    def getPoolSize(self): return len(self._threads)
    def getMaximumPoolSize(self): return self.maxThreads
    def getCorePoolSize(self): return self.coreThreads
    def getActiveCount(self): return self._active
    def getQueue(self): return self._queue
    def getThreadFactory(self): return self.factory
    def __enter__(self): return self
    def __exit__(self, *args): self.shutdown(True)

