def ssl_context(options,server=False):
    supplied=getattr(options,'sslContext',None)
    if supplied is not None: return supplied
    context=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER if server else ssl.PROTOCOL_TLS_CLIENT)
    if not server:
        # The original client's trust manager accepts all certificate chains.
        context.check_hostname=False; context.verify_mode=ssl.CERT_NONE
    cert=getattr(options,'certfile',None) or options.jksFile
    if cert:
        if cert.lower().endswith(('.jks','.p12','.pfx')):
            _load_keystore(context,cert,options.jksStorePassword,options.jksCertificatePassword)
        else: context.load_cert_chain(cert,getattr(options,'keyfile',None),options.jksCertificatePassword)
    elif server: raise ValueError('SSL file and password is null')
    return context

def _load_keystore(context,path,store_password,key_password):
    import pathlib, subprocess, tempfile
    from cryptography.hazmat.primitives.serialization import pkcs12, Encoding, PrivateFormat, NoEncryption
    with tempfile.TemporaryDirectory(prefix='.iot-tls-',dir='.') as directory:
        p12=pathlib.Path(path)
        if path.lower().endswith('.jks'):
            p12=pathlib.Path(directory)/'keys.p12'
            result=subprocess.run(['keytool','-importkeystore','-srckeystore',path,'-srcstorepass',store_password or '', '-destkeystore',str(p12),'-deststoretype','PKCS12','-deststorepass',store_password or '', '-noprompt'],capture_output=True)
            if result.returncode: raise ValueError('Unable to convert JKS keystore')
        key,cert,chain=pkcs12.load_key_and_certificates(p12.read_bytes(),(store_password or '').encode())
        certfile=pathlib.Path(directory)/'cert.pem'; keyfile=pathlib.Path(directory)/'key.pem'
        certfile.write_bytes(cert.public_bytes(Encoding.PEM)+b''.join(c.public_bytes(Encoding.PEM) for c in (chain or [])))
        keyfile.write_bytes(key.private_bytes(Encoding.PEM,PrivateFormat.PKCS8,NoEncryption())); keyfile.chmod(0o600)
        context.load_cert_chain(certfile,keyfile)

def client_socket(options):
