    def __init__(self,serverBean=None,handler=None,baseAuthService=None):
        self.serverBean=serverBean or InitBean(protocol=ProtocolEnum.MQTT,port=1883)
        self.handler=handler or DefaultMqttHandler(MqttHandlerService(baseAuthService=baseAuthService))
        self._stop=threading.Event(); self._channels=set(); self._workers=set(); self._lock=threading.RLock(); self.socket=None; self.thread=None
    def getServerBean(self): return self.serverBean
    def setServerBean(self,value): self.serverBean=value
    def start(self):
        opts=self.serverBean; self._stop.clear()
        self._ssl=ssl_context(opts,True) if opts.ssl else None
        self.socket=socket.socket(socket.AF_INET,socket.SOCK_STREAM)
        self.socket.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,int(opts.reuseaddr))
        self.socket.bind((getattr(opts,'host',None) or IpUtils.getHost(),opts.port)); self.socket.listen(opts.backlog or 128); self.socket.settimeout(.2)
        self.address=self.socket.getsockname(); self.port=self.address[1]
        if opts.mqttHander:
            self.handler=SpringBeanUtils.getBean(opts.mqttHander)
        self.thread=threading.Thread(target=self._accept,name='MQTT-BOSS',daemon=True); self.thread.start(); return self
    def _accept(self):
        while not self._stop.is_set():
            try: conn,_=self.socket.accept()
            except socket.timeout: continue
            except OSError: break
            worker=threading.Thread(target=self._serve,args=(conn,),daemon=True)
            with self._lock: self._workers.add(worker)
            worker.start()
    def _serve(self,conn):
        channel=None; graceful=False
        try:
            opts=self.serverBean
            conn.settimeout(3)
            conn.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,int(opts.tcpNodelay)); conn.setsockopt(socket.SOL_SOCKET,socket.SO_KEEPALIVE,int(opts.keepalive))
            if self._ssl: conn=self._ssl.wrap_socket(conn,server_side=True)
            if opts.protocol in (ProtocolEnum.MQTT_WS_MQTT,ProtocolEnum.MQTT_WS_PAHO): conn=WebSocketSocket.accept(conn,'/mqtt' if opts.protocol==ProtocolEnum.MQTT_WS_PAHO else '/')
            conn.settimeout(.2); channel=Channel(conn); ctx=ChannelHandlerContext(channel)
            with self._lock: self._channels.add(channel)
            decoder=MqttDecoder(); last=time.monotonic()
            while not self._stop.is_set() and channel.isActive():
                try: data=conn.recv(65536)
                except socket.timeout:
                    if opts.heart>0 and time.monotonic()-last>=opts.heart: self.handler.userEventTriggered(ctx,IdleStateEvent(IdleState.READER_IDLE)); break
                    continue
                if not data: break
                last=time.monotonic()
                for message in decoder.feed(data):
                    graceful=message.fixedHeader().messageType()==MqttMessageType.DISCONNECT
                    self.handler.channelRead0(ctx,message)
                    if not channel.isActive(): break
        except (OSError,ValueError,ConnectionException): log.debug('MQTT connection ended',exc_info=True)
        finally:
            if channel:
                if not graceful and channel.isActive(): self.handler.channelInactive(ChannelHandlerContext(channel))
                channel.close()
                with self._lock: self._channels.discard(channel)
            else: conn.close()
            with self._lock: self._workers.discard(threading.current_thread())
    def shutdown(self):
        self._stop.set()
        if self.socket: self.socket.close()
        for channel in list(self._channels): channel.close()
        if self.thread: self.thread.join(2)
        for worker in list(self._workers): worker.join(2)
        transfer=getattr(self.handler.mqttHandlerApi,'messageTransfer',None)
        if transfer: transfer.close()
    close=shutdown
    def __enter__(self): return self.start()
    def __exit__(self,*args): self.shutdown()
