            self.zkClient=KazooClient(hosts=hosts,timeout=sessionTimeout/1000,connection_retry=KazooRetry(max_tries=maxRetries,delay=retriesSleepTime/1000))
        self._connected=False
        def changed(state):
            self.pathChildrenCaches.clear(); self.nodeCaches.clear(); self.treeCaches.clear()
            if state==KazooState.CONNECTED:
                if self._connected: listener.ReconnectedEvent(self.zkClient,ConnectionState.RECONNECTED)
                else: self._connected=True; listener.connectedEvent(self.zkClient,ConnectionState.CONNECTED)
            elif state==KazooState.LOST: listener.lostEvent(self.zkClient,ConnectionState.LOST)
        self.zkClient.add_listener(changed); self.zkClient.start(timeout=connectionTimeout/1000)
    def destory(self):
        for name in ('pathChildrenCaches','nodeCaches','treeCaches'):
            for watcher in getattr(self,name):
                if hasattr(watcher,'_stopped'): watcher._stopped=True
            setattr(self,name,None)
        if self.zkClient is not None: self.zkClient.stop(); self.zkClient.close()
    destroy=destory
    def exists(self,path):
        if self.zkClient is None or path is None: return None
        try: return self.zkClient.exists(path)
        except Exception: log.debug('check node exists failed',exc_info=True); return None
    def checkExists(self,path): return self.exists(path) is not None
    def createNode(self,path,data=None,mode=None):
        if self.zkClient is None or path is None: return False
        try:
            if self.exists(path) is not None: return True
            mode=getattr(mode,'name',mode) or 'PERSISTENT'
            result=self.zkClient.create(path,b'' if data is None else data.encode('utf-8'),ephemeral='EPHEMERAL' in mode,sequence='SEQUENTIAL' in mode,makepath=True)
            return result==path
        except Exception: log.debug('create node failed',exc_info=True); return False
    def deleteNode(self,path,version=None):
        if self.zkClient is None or path is None: return False
        try:
            if self.exists(path) is not None: self.zkClient.delete(path,version=-1 if version is None else version,recursive=True)
            return True
        except Exception: log.debug('delete node failed',exc_info=True); return False
    def getNodeData(self,path):
        if self.exists(path) is None: return None
        try: return self.zkClient.get(path)[0]
        except Exception: log.debug('get node failed',exc_info=True); return None
    def getNodeDataStr(self,path):
        value=self.getNodeData(path); return None if value is None else value.decode('utf-8',errors='replace')
    def setNodeData(self,path,data,version=None):
        if self.exists(path) is None: return False
        try:
            self.zkClient.set(path,data.encode('utf-8') if isinstance(data,str) else data,version=-1 if version is None else version); return True
        except Exception: log.debug('set node failed',exc_info=True); return False
    def readTargetChildsData(self,path):
        if self.exists(path) is None: return None
        try: return {child:self.getNodeDataStr(path.rstrip('/')+'/'+child) for child in self.zkClient.get_children(path)}
        except Exception: log.debug('read children failed',exc_info=True); return None
    def listenerPathChildrenCache(self,path,consumer):
        if consumer is None or self.exists(path) is None: return False
        from kazoo.recipe.watchers import ChildrenWatch, DataWatch
        known={}; watches={}; first=[True]
        def emit(kind,child,data=None,stat=None): consumer(self.zkClient,PathChildrenCacheEvent(type=kind,data=ChildData(path=path.rstrip('/')+'/'+child,data=data,stat=stat)))
        def children_changed(children):
            current=set(children)
            for child in set(known)-current:
                emit('CHILD_REMOVED',child,known.pop(child)); watches.pop(child,None)
            for child in current-set(watches):
                childpath=path.rstrip('/')+'/'+child
                def changed(data,stat,event=None,child=child):
                    if data is None: return
                    if child not in known: kind='CHILD_ADDED'
                    elif known[child]"'!=data: kind='"'CHILD_UPDATED'
                    else: return
                    known[child]=data; emit(kind,child,data,stat)
                watches[child]=DataWatch(self.zkClient,childpath,changed)
                self.nodeCaches.append(watches[child])
            if first[0]: first[0]=False; consumer(self.zkClient,PathChildrenCacheEvent(type='INITIALIZED'))
        try: self.pathChildrenCaches.append(ChildrenWatch(self.zkClient,path,children_changed)); return True
        except Exception: log.debug('listen children failed',exc_info=True); return False
